<?php
declare(strict_types=1);
namespace MailMcp;

final class Panel
{
    public function __construct(private Store $store, private array $config) {}

    public function handle(string $path, string $method): bool
    {
        $routes = ['/login','/logout','/authorize','/authorize/approve','/authorize/switch','/token','/register','/.well-known/oauth-authorization-server'];
        if (!str_starts_with($path, '/admin') && !in_array($path, $routes, true)) return false;
        if (session_status() !== PHP_SESSION_ACTIVE) {
            session_name('mailmcp_admin');
            $host = strtolower((string) (parse_url('http://' . ($_SERVER['HTTP_HOST'] ?? ''), PHP_URL_HOST) ?: ''));
            $localHttp = ($this->config['app_env'] ?? 'production') === 'local' && in_array($host, ['localhost','127.0.0.1','::1'], true);
            session_set_cookie_params(['httponly'=>true,'secure'=>!$localHttp,'samesite'=>'Lax','path'=>'/']);
            session_start();
        }
        if ($path === '/register') { $this->registerClient(); return true; }
        if ($path === '/token') { $this->token(); return true; }
        if ($path === '/.well-known/oauth-authorization-server') { $this->metadata(); return true; }
        if ($path === '/authorize/approve') { $this->approve($method); return true; }
        if ($path === '/authorize/switch') { $this->switchAccount($method); return true; }
        if ($path === '/authorize') { $this->authorize($method); return true; }
        if ($path === '/login') { $this->login($method); return true; }
        if ($path === '/logout') { $this->postOnly($method); unset($_SESSION['account_id']); header('Location: /admin'); return true; }
        $this->admin($path, $method);
        return true;
    }

    private function admin(string $path, string $method): void
    {
        if (!$this->store->hasAdmin()) {
            if ($method === 'POST' && $path === '/admin/setup') { $this->setup(); return; }
            $this->page('Create administrator account', $this->form('/admin/setup', [['email','Email','email'],['password','Password (12+ characters)','password'],['confirm','Confirm password','password']]));
            return;
        }
        if (!$this->signedIn()) { header('Location: /login'); return; }
        $account = $this->currentAccount();
        if (!$account) { unset($_SESSION['account_id']); header('Location: /login'); return; }
        if ($path === '/admin/password' && $method === 'POST') { $this->changePassword($account); return; }
        if ($account['role'] !== 'admin') { $this->siteAccountPage($account); return; }

        if ($path === '/admin/domain/delete' && $method === 'POST') { $this->csrf(); $domain=strtolower(trim($_POST['domain']??''));$this->store->deleteDomain($domain);header('Location: /admin#domains');return; }
        if ($path === '/admin/domain' && $method === 'POST') { $this->saveDomain(); return; }
        if ($path === '/admin/smtp-test' && $method === 'POST') { $this->sendTest(); return; }
        if ($path === '/admin/account' && $method === 'POST') { $this->saveAccount(); return; }
        if ($path === '/admin/account/delete' && $method === 'POST') { $this->csrf();$this->store->deleteAccount((int)($_POST['id']??0));header('Location: /admin#accounts');return; }
        if ($path === '/admin/client/delete' && $method === 'POST') { $this->csrf();$this->store->deleteClient($_POST['client_id']??'');header('Location: /admin#oauth');return; }
        if ($path === '/admin/oauth' && $method === 'POST') { $this->csrf();$ttl=max(300,min(2592000,(int)($_POST['token_ttl']??3600)));$this->store->saveSetting('oauth_token_ttl',(string)$ttl);header('Location: /admin#oauth');return; }
        $this->dashboard($account);
    }

    private function setup(): void
    {
        $this->csrf();$email=filter_var(strtolower(trim($_POST['email']??'')),FILTER_VALIDATE_EMAIL);$pass=(string)($_POST['password']??'');
        if(!$email||strlen($pass)<12||$pass!==($_POST['confirm']??'')){$this->page('Create administrator account','<p>Use a valid email and matching password of at least 12 characters.</p>'.$this->form('/admin/setup',[['email','Email','email'],['password','Password (12+ characters)','password'],['confirm','Confirm password','password']]));return;}
        $this->store->createAdmin($email,$pass);session_regenerate_id(true);$_SESSION['account_id']=1;$_SESSION['csrf']=bin2hex(random_bytes(32));header('Location: /admin');
    }

    private function login(string $method): void
    {
        if($this->signedIn()){header('Location: /admin');return;}
        if($method==='POST'){$this->csrf();$account=$this->store->accountByEmail((string)($_POST['email']??''));if($account&&password_verify((string)($_POST['password']??''),$account['password_hash'])){session_regenerate_id(true);$_SESSION['account_id']=(int)$account['id'];$_SESSION['csrf']=bin2hex(random_bytes(32));$to=(string)($_SESSION['after_login']??'/admin');unset($_SESSION['after_login']);header('Location: '.$to);return;}Logger::warning('account_login_failed');$error='<p class="error">Email or password was incorrect.</p>'; } else {$error='';}
        $this->page('Sign in',$error.$this->form('/login',[['email','Email','email'],['password','Password','password']]));
    }

    private function saveDomain(): void
    {
        $this->csrf();$domain=strtolower(trim($_POST['domain']??''));
        if(!preg_match('/^(?=.{1,253}$)(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$/',$domain)){$this->page('Invalid domain','<p>Enter a valid domain name.</p><p><a href="/admin">Back</a></p>');return;}
        $old=$this->store->domain($domain)??[];$transport=in_array($_POST['transport']??'smtp',['smtp','ses_api','resend'],true)?$_POST['transport']:'smtp';
        $secretField=match($transport){'ses_api'=>'aws_secret_access_key','resend'=>'resend_api_key',default=>'smtp_password'};$secret=(string)($_POST[$secretField]??'');if($transport!=='smtp')$secret=trim($secret);
        $oldSecretKey=match($transport){'ses_api'=>'ses_secret_enc','resend'=>'resend_api_key_enc',default=>'password_enc'};if($secret==='')$secret=$this->decrypt((string)($old[$oldSecretKey]??''));
        $record=['transport'=>$transport,'from_name'=>trim($_POST['from_name']??''),'aws_region'=>trim($_POST['aws_region']??''),'aws_access_key_id'=>trim($_POST['aws_access_key_id']??''),'ses_secret_enc'=>$transport==='ses_api'?$this->encrypt($secret):'','resend_api_key_enc'=>$transport==='resend'?$this->encrypt($secret):'','smtp_host'=>trim($_POST['smtp_host']??''),'smtp_port'=>max(1,min(65535,(int)($_POST['smtp_port']??587))),'smtp_encryption'=>in_array($_POST['smtp_encryption']??'tls',['tls','ssl','none'],true)?$_POST['smtp_encryption']:'tls','smtp_username'=>trim($_POST['smtp_username']??''),'password_enc'=>$transport==='smtp'?$this->encrypt($secret):'','hourly_limit'=>max(1,(int)($_POST['hourly_limit']??40)),'daily_limit'=>max(1,(int)($_POST['daily_limit']??200)),'max_recipients_per_message'=>max(1,(int)($_POST['max_recipients']??10))];
        if($transport==='smtp'&&(!$record['smtp_host']||!$record['smtp_username']||!$secret)){$this->page('Missing SMTP settings','<p>SMTP host, username, and password are required.</p><p><a href="/admin">Back</a></p>');return;}
        if($transport==='ses_api'&&(!$record['aws_region']||!$record['aws_access_key_id']||!$secret)){$this->page('Missing Amazon SES API settings','<p>AWS region, access key ID, and secret access key are required.</p><p><a href="/admin">Back</a></p>');return;}
        if($transport==='resend'&&!$secret){$this->page('Missing Resend settings','<p>A Resend API key is required.</p><p><a href="/admin">Back</a></p>');return;}
        $this->store->saveDomain($domain,$record);header('Location: /admin?notice=domain-saved#domains');
    }

    private function sendTest(): void
    {
        $this->csrf();$domain=strtolower(trim($_POST['domain']??''));$to=filter_var(trim($_POST['to']??''),FILTER_VALIDATE_EMAIL);
        if(!$to||!isset($this->config['domains'][$domain])){$this->page('Mail test failed','<p>Select a configured domain and enter a valid recipient address.</p><p><a href="/admin#smtp-test">Back</a></p>');return;}
        $args=['from'=>'smtp-test@'.$domain,'to'=>[$to],'subject'=>'Mail MCP SMTP test','text'=>'This test message confirms Mail MCP can send through the configured SMTP server for '.$domain.'.'];
        $upload=$_FILES['attachment']??null;
        if(is_array($upload)&&($upload['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_NO_FILE){
            if(($upload['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK||!is_uploaded_file((string)($upload['tmp_name']??''))||($upload['size']??PHP_INT_MAX)>$this->config['max_attachment']){$this->page('Mail test failed','<p>The optional attachment could not be uploaded or exceeds the per-file size limit.</p><p><a href="/admin#smtp-test">Back</a></p>');return;}
            $bytes=file_get_contents((string)$upload['tmp_name']);if($bytes===false){$this->page('Mail test failed','<p>Could not read the uploaded attachment.</p><p><a href="/admin#smtp-test">Back</a></p>');return;}
            $finfo=new \finfo(FILEINFO_MIME_TYPE);$args['attachments']=[['filename'=>(string)($upload['name']??'attachment'),'content_base64'=>base64_encode($bytes),'mime_type'=>$finfo->buffer($bytes)?:'application/octet-stream']];
        }
        try{$messageId=(new Mailer(dirname(__DIR__),$this->config))->send($args,[$domain]);$attachmentText=isset($args['attachments'])?' with attachment '.$this->esc((string)$upload['name']):'';$this->page('Mail test sent','<p>The configured provider accepted the test message'.$attachmentText.' for delivery to '.$this->esc($to).'. Message ID: <code>'.$this->esc($messageId).'</code></p><p>Check the recipient inbox and spam folder to confirm receipt.</p><p><a href="/admin#smtp-test">Back to admin</a></p>');}
        catch(\Throwable $e){Logger::error('smtp_test_failed',['exception'=>$e::class,'domain'=>$domain]);$diagnostic=$e->getPrevious()?->getMessage();$detail=$diagnostic?'<p><strong>Provider response:</strong> <code>'.$this->esc($diagnostic).'</code></p>':'';$this->page('Mail test failed','<p>'.$this->esc($e->getMessage()).'</p>'.$detail.'<p>Check <code>storage/logs/mail-mcp-'.gmdate('Y-m-d').'.log</code> for details. Request ID: <code>'.$this->esc(Logger::requestId()).'</code></p><p><a href="/admin#smtp-test">Back to admin</a></p>');}
    }

    private function saveAccount(): void
    {
        $this->csrf();$email=filter_var(strtolower(trim($_POST['email']??'')),FILTER_VALIDATE_EMAIL);$password=(string)($_POST['password']??'');$domains=array_values(array_unique(array_filter((array)($_POST['domains']??[]),'is_string')));$allDomains=array_keys($this->store->domains());
        if(!$email||array_diff($domains,$allDomains)){$this->page('Account not saved','<p>Enter a valid email and select only configured domains.</p><p><a href="/admin#accounts">Back</a></p>');return;}
        $existing=$this->store->accountByEmail($email);
        if($existing){if($password!==''&&strlen($password)<12){$this->page('Account not saved','<p>New passwords must be at least 12 characters.</p><p><a href="/admin#accounts">Back</a></p>');return;}if($password!==''&&$existing['role']==='site')$this->store->saveAccountPassword((int)$existing['id'],$password);$this->store->setAccountDomains((int)$existing['id'],$domains);}
        else{if(strlen($password)<12){$this->page('Account not saved','<p>New account passwords must be at least 12 characters.</p><p><a href="/admin#accounts">Back</a></p>');return;}$this->store->createAccount($email,$password,$domains);}
        header('Location: /admin#accounts');
    }

    private function changePassword(array $account): void
    {
        $this->csrf();if(!password_verify((string)($_POST['current_password']??''),$account['password_hash'])||strlen((string)($_POST['new_password']??''))<12||($_POST['new_password']??'')!==($_POST['confirm']??'')){$this->page('Password not changed','<p>Check the current password and use matching new passwords of at least 12 characters.</p><p><a href="/admin">Back</a></p>');return;}
        $this->store->saveAccountPassword((int)$account['id'],(string)$_POST['new_password']);$this->page('Password updated','<p>Your password was updated.</p><p><a href="/admin">Continue</a></p>');
    }

    private function dashboard(array $account): void
    {
        $domains=$this->store->domains();$domainRows='';foreach($domains as $domain=>$d){$name=$this->esc($domain);$editUrl='/admin?edit_domain='.rawurlencode($domain).'#domain-form';$domainRows.='<tr><td><span class="domain-name">'.$name.'</span><small class="host-line">'.$this->esc(match($d['transport']??'smtp'){'ses_api'=>'Amazon SES API · '.($d['aws_region']??''),'resend'=>'Resend API','smtp'=>(string)($d['smtp_host']??''),default=>'Unknown provider'}).'</small></td><td><span class="port-tag">'.(($d['transport']??'smtp')==='smtp'?(int)($d['smtp_port']??0).' · '.strtoupper($this->esc($d['smtp_encryption']??'tls')):strtoupper($this->esc(match($d['transport']??'smtp'){'ses_api'=>'SES API','resend'=>'Resend',default=>'Unknown'}))).'</span></td><td>'.(int)($d['hourly_limit']??0).' / hour <span class="muted">·</span> '.(int)($d['daily_limit']??0).' / day</td><td class="row-actions"><a class="button quiet" href="'.$editUrl.'">Edit</a><form method="post" action="/admin/domain/delete">'.$this->csrfField().'<input type="hidden" name="domain" value="'.$name.'"><button class="danger">Remove</button></form></td></tr>';}
        $domainChoices='';foreach($domains as $domain=>$unused){$escaped=$this->esc($domain);$domainChoices.='<label class="check"><input type="checkbox" name="domains[]" value="'.$escaped.'"> '.$escaped.'</label>';}
        $accountRows='';foreach($this->store->accounts() as $user){$id=(int)$user['id'];$userDomains=array_map([$this,'esc'],$this->store->accountDomains($id));$accountRows.='<tr><td>'.$this->esc($user['email']).'</td><td>'.($user['role']==='admin'?'Administrator':'Site account').'</td><td>'.($userDomains?$this->esc(implode(', ',$userDomains)):'<em>No domains assigned</em>').'</td><td>'.($user['role']==='site'?'<form method="post" action="/admin/account/delete">'.$this->csrfField().'<input type="hidden" name="id" value="'.$id.'"><button>Remove</button></form>':'—').'</td></tr>';}
        $clients='';foreach($this->store->clients() as $c){$m=json_decode($c['metadata'],true)?:[];$id=$this->esc($c['client_id']);$clients.='<tr><td><code>'.$id.'</code></td><td>'.$this->esc(implode(', ',array_slice($m['redirect_uris']??[],0,2))).'</td><td><form method="post" action="/admin/client/delete">'.$this->csrfField().'<input type="hidden" name="client_id" value="'.$id.'"><button>Revoke</button></form></td></tr>';}
        $ttl=(int)$this->store->setting('oauth_token_ttl','3600');$selectedDomain=(string)($_GET['edit_domain']??'');$selected=$selectedDomain!==''?($domains[$selectedDomain]??null):null;$domainForm=$this->domainForm($selectedDomain,$selected);
        $testOptions='';foreach($domains as $domain=>$unused)$testOptions.='<option value="'.$this->esc($domain).'">'.$this->esc($domain).'</option>';
        $notice=($_GET['notice']??'')==='domain-saved'?'<div class="notice">Domain delivery settings saved.</div>':'';
        $domainTable=$domainRows?'<div class="table-scroll"><table><thead><tr><th>Sending domain and host</th><th>Connection</th><th>Message limits</th><th></th></tr></thead><tbody>'.$domainRows.'</tbody></table></div>':'<div class="empty"><strong>No sending domains yet</strong><span>Add a sending domain and choose SMTP, Resend, or Amazon SES API v2.</span></div>';
        $accountsTable=$accountRows?'<div class="table-scroll"><table><thead><tr><th>Account</th><th>Type</th><th>Allowed sender domains</th><th></th></tr></thead><tbody>'.$accountRows.'</tbody></table></div>':'<div class="empty">No accounts yet.</div>';
        $clientTable=$clients?'<div class="table-scroll"><table><thead><tr><th>OAuth client</th><th>Redirect URI</th><th></th></tr></thead><tbody>'.$clients.'</tbody></table></div>':'<div class="empty">No OAuth clients registered yet.</div>';
        $html='<header class="masthead"><div class="brand-mark">M</div><div class="brand-copy"><strong>Mail MCP</strong><span>Mail operations</span></div><div class="masthead-right"><span class="signed-in">'.$this->esc($account['email']).'</span>'.$this->logoutForm().'</div></header><nav class="section-nav" aria-label="Admin sections"><a href="#domains">Domains</a><a href="#smtp-test">Test delivery</a><a href="#accounts">Accounts</a><a href="#oauth">OAuth</a></nav>'.$notice.'<section class="intro"><div><p class="eyebrow">MAIL DELIVERY CONTROL</p><h2>Manage sending access</h2><p>Configure delivery connections, verify delivery, and limit each account to its assigned domains.</p></div><div class="endpoint"><span>MCP endpoint</span><code>'.$this->esc($this->config['base_url']).'</code></div></section><section class="section" id="domains"><div class="section-heading"><div><h2>Sending domains</h2></div><span class="count">'.count($domains).' configured</span></div>'.$domainTable.'<div class="editor" id="domain-form"><div class="editor-heading"><div><h3>'.($selected?'Edit delivery settings':'Add a sending domain').'</h3><p>'.($selected?'Update the connection details for '.$this->esc($selectedDomain).'.':'Each sender domain uses its own provider credentials and rate limits.').'</p></div>'.($selected?'<a class="button quiet" href="/admin#domains">Cancel edit</a>':'').'</div>'.$domainForm.'</div></section><section class="section test-section" id="smtp-test"><div class="section-heading"><div><h2>Test mail delivery</h2></div><span class="test-mark">REAL EMAIL</span></div><p class="section-copy">Send a test message through the selected domain connection. Attach a small file to check attachment delivery too. Each test counts against the domain’s hourly and daily limits.</p><form method="post" enctype="multipart/form-data" action="/admin/smtp-test" class="form-grid">'.$this->csrfField().'<label>Sending domain<select name="domain" required>'.$testOptions.'</select></label><label>Recipient address<input name="to" type="email" required placeholder="you@example.com"></label><label class="wide">Optional attachment<input name="attachment" type="file"></label><div class="wide"><button class="primary">Send test email</button></div></form></section><section class="section" id="accounts"><div class="section-heading"><div><h2>Accounts and access</h2></div></div><p class="section-copy">Every account, including the administrator, can send only from assigned domains. Enter an existing email to update its access; leave the password blank to keep it. Change your own password in the section below.</p>'.$accountsTable.'<div class="editor"><div class="editor-heading"><div><h3>Add or update an account</h3><p>Assign only the domains this account needs.</p></div></div><form method="post" action="/admin/account">'.$this->csrfField().'<div class="form-grid"><label>Email<input type="email" name="email" required></label><label>Password<input type="password" name="password" placeholder="Required for a new account; blank keeps existing"></label><fieldset class="wide"><legend>Allowed sending domains</legend>'.$domainChoices.'</fieldset><div class="wide"><button class="primary">Save account access</button></div></div></form></div></section><section class="section" id="oauth"><div class="section-heading"><div><h2>OAuth connections</h2></div></div><p class="section-copy">Each approval is tied to the account that signs in and that account’s assigned domains.</p><form method="post" action="/admin/oauth" class="form-grid">'.$this->csrfField().'<label>Access token lifetime in seconds<input name="token_ttl" type="number" min="300" max="2592000" value="'.$ttl.'"></label><div class="align-end"><button class="secondary">Save token lifetime</button></div></form><h3 class="subheading">Registered clients</h3>'.$clientTable.'</section><section class="section" id="password"><div class="section-heading"><div><h2>Administrator password</h2></div></div>'.$this->passwordForm().'</section><footer class="page-foot">Mail MCP · Private sending infrastructure</footer>';
        $this->page('Mail MCP administration',$html);
    }

    private function domainForm(string $domain,?array $settings): string
    {
        $settings=$settings??[];$editing=$domain!==''&&$settings!==null;$esc=fn(string $v):string=>$this->esc($v);$value=fn(string $k,string $fallback='')=>$esc((string)($settings[$k]??$fallback));
        $domainInput='<label>Sending domain<input name="domain" type="text" required value="'.$esc($domain).'" placeholder="example.com"'.($editing?' readonly':'').'></label>';
        $transport=(string)($settings['transport']??'smtp');$transportOptions='';foreach(['smtp'=>'SMTP server','resend'=>'Resend API','ses_api'=>'Amazon SES API v2'] as $key=>$label)$transportOptions.='<option value="'.$key.'"'.($transport===$key?' selected':'').'>'.$label.'</option>';
        $encryption=(string)($settings['smtp_encryption']??'tls');$options='';foreach(['tls'=>'STARTTLS · port 587','ssl'=>'TLS wrapper · port 465','none'=>'None · private network only'] as $key=>$label)$options.='<option value="'.$key.'"'.($encryption===$key?' selected':'').'>'.$label.'</option>';
        $secretRequired=$editing?'':' required';
        return '<form method="post" action="/admin/domain">'.$this->csrfField().'<div class="form-grid">'.$domainInput.'<label>From name<input name="from_name" type="text" value="'.$value('from_name').'" placeholder="Example Support"></label><label>Delivery method<select name="transport" id="transport">'.$transportOptions.'</select></label><div class="wide" data-ses><fieldset><legend>Amazon SES API v2</legend><div class="form-grid"><label>AWS region<input name="aws_region" data-ses-required value="'.$value('aws_region','us-east-1').'" placeholder="us-east-1"></label><label>IAM access key ID<input name="aws_access_key_id" data-ses-required value="'.$value('aws_access_key_id').'" autocomplete="off"></label><label class="wide">IAM secret access key<input name="aws_secret_access_key" data-ses-required'.($editing?' data-ses-optional':'').' type="password"'.$secretRequired.' autocomplete="new-password" placeholder="'.($editing?'Leave blank to keep saved secret':'Enter IAM secret access key').'"></label></div><small>Use an IAM key with ses:SendEmail permission. Verify this sender domain in SES.</small></fieldset></div><div class="wide" data-resend><fieldset><legend>Resend API</legend><label>Resend API key<input name="resend_api_key" data-resend-required'.($editing?' data-resend-optional':'').' type="password"'.$secretRequired.' autocomplete="new-password" placeholder="'.($editing?'Leave blank to keep saved key':'re_…').'"></label><small>Use a Resend API key with email sending access. Verify the sender domain in Resend.</small></fieldset></div><div class="wide" data-smtp><fieldset><legend>SMTP server</legend><div class="form-grid"><label class="wide">SMTP host<input name="smtp_host" data-smtp-required value="'.$value('smtp_host').'" placeholder="email-smtp.us-east-1.amazonaws.com"></label><label>SMTP port<input name="smtp_port" type="number" min="1" max="65535" data-smtp-required value="'.$value('smtp_port','587').'"></label><label>Encryption<select name="smtp_encryption">'.$options.'</select></label><label>SMTP username<input name="smtp_username" data-smtp-required value="'.$value('smtp_username').'" autocomplete="off"></label><label>SMTP password<input name="smtp_password" type="password"'.($editing?'':' data-smtp-required').' autocomplete="new-password" placeholder="'.($editing?'Leave blank to keep saved password':'Enter SMTP password').'"></label></div></fieldset></div><label>Messages per hour<input name="hourly_limit" type="number" min="1" required value="'.$value('hourly_limit','40').'"></label><label>Messages per day<input name="daily_limit" type="number" min="1" required value="'.$value('daily_limit','200').'"></label><label>Recipients per message<input name="max_recipients" type="number" min="1" required value="'.$value('max_recipients_per_message','10').'"></label><div class="wide"><button class="primary">'.($editing?'Save domain settings':'Add sending domain').'</button></div></div><script>const t=document.getElementById("transport"),s=document.querySelector("[data-smtp]"),r=document.querySelector("[data-resend]"),a=document.querySelector("[data-ses]");function toggleTransport(){const smtp=t.value==="smtp",resend=t.value==="resend",ses=t.value==="ses_api";s.hidden=!smtp;r.hidden=!resend;a.hidden=!ses;s.querySelectorAll("[data-smtp-required]").forEach(e=>e.required=smtp);r.querySelectorAll("[data-resend-required]").forEach(e=>e.required=resend&&!e.hasAttribute("data-resend-optional"));a.querySelectorAll("[data-ses-required]").forEach(e=>e.required=ses&&!e.hasAttribute("data-ses-optional"))}t.addEventListener("change",toggleTransport);toggleTransport();</script></form>';
    }

    private function siteAccountPage(array $account): void
    {
        $domains=$this->store->accountDomains((int)$account['id']);$html='<p>Signed in as '.$this->esc($account['email']).'. This account may send from: <strong>'.$this->esc($domains?implode(', ',$domains):'no domains assigned').'</strong>.</p>'.$this->logoutForm().'<h2>Change password</h2>'.$this->passwordForm();$this->page('Mail MCP site account',$html);
    }
    private function passwordForm(): string {return $this->form('/admin/password',[['current_password','Current password','password'],['new_password','New password (12+ characters)','password'],['confirm','Confirm new password','password']]);}
    private function logoutForm(): string {return '<form method="post" action="/logout">'.$this->csrfField().'<button>Sign out</button></form>';}

    private function registerClient(): void
    {
